"""IoT dashboard frontend pages — DeviceFleetPage and SensorChartPage."""
from __future__ import annotations

# ---------------------------------------------------------------------------
# DeviceFleetPage.tsx — Device grid with online/offline status badges
# ---------------------------------------------------------------------------

DEVICE_FLEET_PAGE_TSX = '''\
// DeviceFleetPage.tsx — Auto-generated by AetherOS p05_frontend (iot domain)
import { useQuery } from '@tanstack/react-query'
import { Wifi, WifiOff, AlertTriangle, Activity, Server } from 'lucide-react'

const API = import.meta.env.VITE_API_URL ?? ''
const auth = () => ({ Authorization: `Bearer ${localStorage.getItem('token') ?? ''}` })

type DeviceStatus = 'online' | 'offline' | 'error' | 'maintenance'

interface Device {
  device_id: string
  name: string
  device_type: string
  status: DeviceStatus
  last_seen?: string
  location?: string
  firmware_version?: string
}

interface FleetSummary {
  total_devices: number
  online: number
  offline: number
  in_alert: number
}

const STATUS_CONFIG = {
  online:      { icon: Wifi,         badge: 'bg-green-100 text-green-800',  dot: 'bg-green-500'  },
  offline:     { icon: WifiOff,      badge: 'bg-gray-100 text-gray-600',    dot: 'bg-gray-400'   },
  error:       { icon: AlertTriangle,badge: 'bg-red-100 text-red-800',      dot: 'bg-red-500'    },
  maintenance: { icon: Activity,     badge: 'bg-amber-100 text-amber-800',  dot: 'bg-amber-400'  },
} as const

function DeviceCard({ device }: { device: Device }) {
  const cfg = STATUS_CONFIG[device.status] ?? STATUS_CONFIG.offline
  const Icon = cfg.icon
  return (
    <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-sm hover:shadow-md transition-shadow">
      <div className="flex items-start justify-between mb-3">
        <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${cfg.badge}`}>
          <span className={`inline-block h-1.5 w-1.5 rounded-full ${cfg.dot}`} />
          <Icon className="h-3 w-3" />{device.status}
        </span>
        <Server className="h-4 w-4 text-gray-400" />
      </div>
      <h3 className="text-sm font-semibold text-gray-900 mb-1">{device.name}</h3>
      <p className="text-xs text-gray-500 mb-1">{device.device_type}</p>
      {device.location && <p className="text-xs text-gray-400 mb-1">{device.location}</p>}
      {device.last_seen && (
        <p className="text-xs text-gray-400">
          Last seen: {new Date(device.last_seen).toLocaleString()}
        </p>
      )}
      <div className="mt-3 pt-3 border-t border-gray-100">
        <a
          href={`/app-preview/devices/${device.device_id}/readings`}
          className="block rounded-lg bg-indigo-50 px-2 py-1.5 text-xs font-medium text-indigo-700 text-center hover:bg-indigo-100 transition-colors"
        >
          View Sensor Readings
        </a>
      </div>
    </div>
  )
}

export default function DeviceFleetPage() {
  const { data: summary } = useQuery<FleetSummary>({
    queryKey: ['fleet-dashboard'],
    queryFn: async () => {
      const res = await fetch(`${API}/api/iot/fleet/dashboard`, { headers: auth() })
      if (!res.ok) return { total_devices: 0, online: 0, offline: 0, in_alert: 0 }
      return res.json()
    },
    refetchInterval: 30_000,
  })

  const { data: devices = [], isLoading } = useQuery<Device[]>({
    queryKey: ['iot-devices'],
    queryFn: async () => {
      const res = await fetch(`${API}/api/iot/devices`, { headers: auth() })
      if (!res.ok) throw new Error('Device fetch failed')
      return res.json()
    },
    refetchInterval: 30_000,
  })

  const stats = [
    { label: 'Total',    value: summary?.total_devices ?? devices.length,                                 color: 'text-gray-900'   },
    { label: 'Online',   value: summary?.online  ?? devices.filter(d => d.status === 'online').length,   color: 'text-green-600'  },
    { label: 'Offline',  value: summary?.offline ?? devices.filter(d => d.status === 'offline').length,  color: 'text-gray-400'   },
    { label: 'In Alert', value: summary?.in_alert ?? devices.filter(d => d.status === 'error').length,   color: 'text-red-500'    },
  ]

  return (
    <div className="mx-auto max-w-6xl px-4 py-6">
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Device Fleet</h1>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-8">
        {stats.map(s => (
          <div key={s.label} className="rounded-xl border border-gray-200 bg-white p-4 text-center shadow-sm">
            <p className={`text-3xl font-bold ${s.color}`}>{s.value}</p>
            <p className="text-xs text-gray-500 mt-1">{s.label}</p>
          </div>
        ))}
      </div>

      {isLoading ? (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {Array.from({ length: 8 }).map((_, i) => (
            <div key={i} className="h-44 rounded-xl bg-gray-100 animate-pulse" />
          ))}
        </div>
      ) : devices.length === 0 ? (
        <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-gray-300 py-16">
          <Server className="h-10 w-10 text-gray-300 mb-3" />
          <p className="text-gray-400 text-sm">No devices registered yet.</p>
        </div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {devices.map(d => <DeviceCard key={d.device_id} device={d} />)}
        </div>
      )}
    </div>
  )
}
'''

# ---------------------------------------------------------------------------
# SensorChartPage.tsx — Recharts LineChart for device time-series readings
# ---------------------------------------------------------------------------

SENSOR_CHART_PAGE_TSX = '''\
// SensorChartPage.tsx — Auto-generated by AetherOS p05_frontend (iot domain)
// Recharts LineChart with date-range picker for per-device sensor readings.
import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer,
} from 'recharts'
import { Activity } from 'lucide-react'

const API = import.meta.env.VITE_API_URL ?? ''
const auth = () => ({ Authorization: `Bearer ${localStorage.getItem('token') ?? ''}` })

const COLORS = ['#6366f1', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6']

interface Reading {
  timestamp: string
  metric_name: string
  value: number
  unit?: string
}

interface ChartPoint { time: string; [metric: string]: string | number }

function buildChartData(readings: Reading[]): ChartPoint[] {
  const byTime: Record<string, ChartPoint> = {}
  readings.forEach(r => {
    const t = new Date(r.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    byTime[t] = byTime[t] ?? { time: t }
    byTime[t][r.metric_name] = r.value
  })
  return Object.values(byTime).sort((a, b) => String(a.time).localeCompare(String(b.time)))
}

function getMetrics(readings: Reading[]): string[] {
  return [...new Set(readings.map(r => r.metric_name))]
}

function isoLocal(offsetHours = 0): string {
  const d = new Date(Date.now() + offsetHours * 3_600_000)
  return d.toISOString().slice(0, 16)
}

export default function SensorChartPage() {
  const deviceId = (() => {
    const m = window.location.pathname.match(/\/devices\/([^/]+)\/readings/)
    return m?.[1] ?? 'unknown'
  })()

  const [startDate, setStartDate] = useState(() => isoLocal(-24))
  const [endDate, setEndDate]     = useState(() => isoLocal(0))

  const { data: readings = [], isLoading } = useQuery<Reading[]>({
    queryKey: ['sensor-readings', deviceId, startDate, endDate],
    queryFn: async () => {
      const p = new URLSearchParams({ start: startDate, end: endDate })
      const res = await fetch(`${API}/api/iot/devices/${deviceId}/readings?${p}`, { headers: auth() })
      if (!res.ok) return []
      return res.json()
    },
  })

  const chartData = buildChartData(readings)
  const metrics   = getMetrics(readings)

  return (
    <div className="mx-auto max-w-5xl px-4 py-6">
      <div className="flex items-center gap-3 mb-6">
        <Activity className="h-6 w-6 text-indigo-600" />
        <h1 className="text-2xl font-bold text-gray-900">Sensor Readings</h1>
        <span className="text-sm text-gray-400 font-mono">{deviceId}</span>
      </div>

      <div className="flex flex-wrap gap-4 mb-6 p-4 rounded-xl border border-gray-200 bg-white shadow-sm">
        {([['From', startDate, setStartDate], ['To', endDate, setEndDate]] as const).map(([label, val, set]) => (
          <div key={label} className="flex items-center gap-2">
            <label className="text-xs font-medium text-gray-600">{label}</label>
            <input
              type="datetime-local"
              value={val}
              onChange={e => set(e.target.value)}
              className="rounded-lg border border-gray-300 px-3 py-1.5 text-xs focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
            />
          </div>
        ))}
      </div>

      {isLoading ? (
        <div className="h-80 rounded-xl bg-gray-100 animate-pulse" />
      ) : readings.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-80 rounded-xl border border-dashed border-gray-300 bg-white">
          <Activity className="h-10 w-10 text-gray-300 mb-3" />
          <p className="text-gray-400 text-sm">No readings in this time range.</p>
        </div>
      ) : (
        <div className="rounded-xl border border-gray-200 bg-white p-6 shadow-sm">
          <ResponsiveContainer width="100%" height={320}>
            <LineChart data={chartData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="time" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip contentStyle={{ borderRadius: '8px', fontSize: '12px' }} />
              <Legend wrapperStyle={{ fontSize: '12px' }} />
              {metrics.map((metric, i) => (
                <Line
                  key={metric}
                  type="monotone"
                  dataKey={metric}
                  stroke={COLORS[i % COLORS.length]}
                  strokeWidth={2}
                  dot={false}
                  activeDot={{ r: 4 }}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
          <p className="text-xs text-gray-400 mt-3 text-center">
            {readings.length} readings · {metrics.length} metric{metrics.length !== 1 ? 's' : ''}
          </p>
        </div>
      )}
    </div>
  )
}
'''
